-- =====================================================================================
-- QBank seed data — 5 môn, mỗi môn 3 chương và 100 câu hỏi trắc nghiệm (tổng 500 câu).
--
-- SINH TỰ ĐỘNG từ QBankDataInitializer.java, cùng công thức content_hash.
-- Dùng khi muốn nạp dữ liệu mà KHÔNG chạy Spring Boot (hoặc chạy lại cho sạch).
--
-- CÁCH DÙNG
--   mysql -u root -p <ten_database> < be-web-admin/sql/2026-11-23-qbank-seed-500-cau.sql
--
-- AN TOÀN
--   * Idempotent: mỗi môn dùng subject_code cố định + INSERT IGNORE, chạy lại không nhân đôi.
--   * Không xoá dữ liệu sẵn có. Muốn nạp lại sạch thì dùng file reset ở cuối.
--   * content_hash tính đúng chuẩn QuestionContentHasher (NFC + trim + gộp khoảng trắng,
--     phân tách bằng 0x01, SHA-256 hex) nên khớp với câu tạo qua API.
--
-- ĐIỀU KIỆN: đã chạy be-web-admin/sql/2026-11-19-02-business-tables.sql (có ntt_subjects,
-- ntt_topics, ntt_questions, ntt_question_revisions).
-- =====================================================================================

SET NAMES utf8mb4;
SET @admin_id := (SELECT MIN(admin_id) FROM ntt_admins);

